                break
            window_sum = new_sum
            cur_cost = new_cost
            r += 1

        # 以 l 为左端点，右端点可取 [l, r-1]
        cnt += r - l

        # 左端点右移
        if r > l:
            cur_cost -= (r - l) * a[l]
            window_sum -= a[l]
        else:
            r = l + 1

    return cnt


def kth_smallest_cost(a, k):
    n = len(a)
    # 计算整个区间的加权成本作为二分上界
    running = 0
    high = 0
    for x in a:
